UPDATE `quest_template` SET `OfferRewardText` = 'You''ve done an excellent job tracking down and combating the cultists, but I fear they are right about one thing. We will never know if we''ve gotten them all.' WHERE `Id` = 27780;
UPDATE `quest_template` SET `OfferRewardText` = 'Good, you''re back. We know where Cho''gall''s ultimate weapon is located!' WHERE `Id` = 27782;
UPDATE `quest_template` SET `OfferRewardText` = 'Good, you''re back. It''s about time. We know where Cho''gall''s ultimate weapon is located!' WHERE `Id` = 27783;
