UPDATE `quest_template` SET `RequestItemsText` = 'You don''t have any Bread of the Dead, do you?', `OfferRewardText` = 'Ah, more delicious Bread of the Dead, thank you! Please, take this in return... a little something fun for the holiday.' WHERE `Id` = 27846;
UPDATE `quest_template` SET `OfferRewardText` = 'You''ve followed orders well, $N. On behalf of the crown, I''m rewarding you for your bravery on the battlefield.' WHERE `Id` = 27849;
