UPDATE `quest_template` SET `RequestItemsText` = 'The ogres are powerful, but without help they will fall to the Alliance riders.', `OfferRewardText` = 'You are a true champion, $N, to take the lives of so many on the battlefield. I hope it will be enough to save Stonard.' WHERE `Id` = 27854;
UPDATE `quest_template` SET `RequestItemsText` = 'Is there a problem, $N?', `OfferRewardText` = 'With no link to the outside, the Alliance must rely on what they''ve brought to the swamp. We shall see if they can handle our home environment.' WHERE `Id` = 27855;
UPDATE `quest_template` SET `RequestItemsText` = 'The spirits will watch over us, $N.', `OfferRewardText` = 'You honor both the dead and the living with your courage, $N.' WHERE `Id` = 27856;
UPDATE `quest_template` SET `RequestItemsText` = 'There is no time! Go! Fight!', `OfferRewardText` = 'The Alliance is driven out! Stonard will be safe, thanks to your ferocity. Lok''tar Ogar!' WHERE `Id` = 27857;
UPDATE `quest_template` SET `OfferRewardText` = 'Thankfully, you have avoided Deathwing''s notice.  Rhea and the black dragon egg, however, may not have been so lucky...' WHERE `Id` = 27858;
