UPDATE `quest_template` SET `RequestItemsText` = 'You got enough bug goo for the first batch?', `OfferRewardText` = 'Oh yeah! This is going to be the greatest flavor in the world!$B$BLook out, Tigule and Foror!!!' WHERE `Id` = 28045;
