UPDATE `quest_template` SET `RequestItemsText` = 'That is one huge pillow! Where''d you get it from?', `OfferRewardText` = 'This is better than even I could have thought possible! The Chambermaid''s magical pillow is mine! You better believe you''re going to get a nice reward for this accomplishment, $N!' WHERE `Id` = 28058;
UPDATE `quest_template` SET `OfferRewardText` = 'You killed him?  We have been trying to take that guy out for weeks!  We thank you, $N.' WHERE `Id` = 28059;
