UPDATE `quest_template` SET `RequestItemsText` = 'There are still more prisoners, $N.', `OfferRewardText` = 'You give so much of yourself without requiring anything in return.$B$BThe people of Thousand Needles are grateful, as am I.' WHERE `Id` = 28127;
UPDATE `quest_template` SET `RequestItemsText` = 'Xavalis lurks in Shadow Hold in Jaedenar.' WHERE `Id` = 28129;
