UPDATE `quest_template` SET `RequestItemsText` = 'Have you fed my spider?' WHERE `Id` = 28146;
UPDATE `quest_template` SET `OfferRewardText` = 'What did you manage to get? I suppose we can piece something together from this.$B$BAfter all, you''re not joining the cult. We just need to fool a few ogres.' WHERE `Id` = 28147;
