UPDATE `quest_template` SET `RequestItemsText` = 'Don''t fear de darkness, mon.', `OfferRewardText` = 'You see! De dead be nothing to be scared of. You brought de light to de darkness, mon, and never flinched.$B$BWe can use dis cave now as a base of operations in de northern Highlands. You''re de best, $N!' WHERE `Id` = 28170;
