UPDATE `quest_template` SET `RequestItemsText` = 'You have trouble finding them?  They''re to the south, $N.', `OfferRewardText` = 'Glad to have you on my side, $N.  Bravo Company reunited, right?$B$bOh, did I mention that Troteman''s here, too?' WHERE `Id` = 28416;
UPDATE `quest_template` SET `OfferRewardText` = 'I will see to it that these dragons are taken care of.' WHERE `Id` = 28417;
UPDATE `quest_template` SET `RequestItemsText` = 'I suppose you don''t have what it takes.$B$bThat''s fine.  I can fight this war myself.', `OfferRewardText` = 'So you''re in, then?$B$bGood.' WHERE `Id` = 28418;
UPDATE `quest_template` SET `OfferRewardText` = 'Those scorpids are easy to underestimate.  You''re lucky you didn''t end up on the end of one of these barbs.  Or maybe you''re just good.$B$bI''ll add these to the stockpile.  We''re not done yet, $R.' WHERE `Id` = 28419;
UPDATE `quest_template` SET `OfferRewardText` = 'Believe me, $N... I''m just as anxious to get to the killing as you are.  We''ve got to keep to the plan.  The armageddon will come soon enough.$B$bI''ll keep these hides here.' WHERE `Id` = 28420;
UPDATE `quest_template` SET `OfferRewardText` = 'This is exactly what we need.$B$bDon''t worry, $N... the killing will come soon enough.' WHERE `Id` = 28421;
