UPDATE `quest_template` SET `OfferRewardText` = 'That''s it?  That''s your disguise?  I''m feeling less confident about our chances. But still confident.' WHERE `Id` = 28428;
UPDATE `quest_template` SET `OfferRewardText` = 'That''s it?  That''s your disguise?  I''m feeling less confident about our chances. But still confident.' WHERE `Id` = 28429;
