UPDATE `quest_template` SET `RequestItemsText` = 'Oh, you''re asking for it now, grunt.', `OfferRewardText` = 'Hmph.  Good work, grunt.' WHERE `Id` = 28433;
UPDATE `quest_template` SET `OfferRewardText` = 'Not only did you pull off the executions, you managed to make them all look like accidents.$B$bYou were the right $R for this undercover work.  Good job, soldier.' WHERE `Id` = 28434;
