UPDATE `quest_template` SET `RequestItemsText` = 'Do I have to use the cudgel on you, soldier?  Get back out there!', `OfferRewardText` = 'I have a feeling we''ll be hearing about you and your exploits for a long time, soldier.  I look forward to fighting by your side in Redridge.$B$bYou are dismissed.' WHERE `Id` = 28439;
