UPDATE `quest_template` SET `RequestItemsText` = 'It is done, $C.', `OfferRewardText` = 'Arygos''s machinations have been undone, thanks in great part to you, $C.$B$BAs my first act as aspect of the blue dragonflight, your bond with Tarecgosa is now made stable.$B$BThe power that once sustained that bond I now infuse into your staff.$B$BMay the Runestaff of Nordrassil serve you well!' WHERE `Id` = 29285;
