UPDATE `quest_template` SET `OfferRewardText` = 'Feeding all those sentinels is much easier with your help. Nobody had to wait in line for their meal this time.' WHERE `Id` = 29318;
UPDATE `quest_template` SET `RequestItemsText` = 'If all of our fishermen pitch in, it won''t take long to rebuild our supplies.', `OfferRewardText` = 'These are beautiful! Thank you, $N. I''ll set them out to dry.' WHERE `Id` = 29323;
UPDATE `quest_template` SET `RequestItemsText` = 'Have you had any luck finding Aquinne''s missing pendant? I must''ve caught fifty of those monsters and I have nothing to show for it!', `OfferRewardText` = '<Astaia takes the pendant from you.>$B$BUnderneath all the slime and tarnish, I think this is it! Aquinne will be so happy to have this back... after a thorough cleaning, of course. I can''t thank you enough, $N.' WHERE `Id` = 29324;
UPDATE `quest_template` SET `RequestItemsText` = 'It''s impossible to catch octopi with a fishing line, so you''re just going to have to grab them!', `OfferRewardText` = 'These are going to be delicious, I can already tell! Thanks, $N!' WHERE `Id` = 29325;
