UPDATE `quest_template` SET `RequestItemsText` = 'Have you brought the crate as we discussed?', `OfferRewardText` = 'Ah, you did manage to get the crate before Archmage Xylem''s man could get it out of the city. Excellent!' WHERE `Id` = 29411;
