UPDATE `quest_template` SET `RequestItemsText` = 'We are ready to fight the mogu leader whenever you are.', `OfferRewardText` = 'This is extremely unsettling. If mogu are banding together like this all over the continent, it could become a major threat to Pandaria.' WHERE `Id` = 29670;
UPDATE `quest_template` SET `OfferRewardText` = 'Creatures of the void are naturally chaotic. They are a necessary part of the universe, but they must be kept in check by the Light.' WHERE `Id` = 29674;
