UPDATE `quest_template` SET `RequestItemsText` = 'So much fishin'' in store! I can hardly wait to start my waitin''.', `OfferRewardText` = 'I like a $R who isn''t too lofty to help a humble merchant out. Thank you.' WHERE `Id` = 30339;
