UPDATE `quest_template` SET `RequestItemsText` = 'Did ye find my missing gears and bolts?', `OfferRewardText` = 'Well these aren''t as good as she deserves, but it will have to work.$B$B<Sully pats the dismantled ballista.>$B$bI''ll get ''er up and runnin'' in no time, just ye watch!' WHERE `Id` = 30565;
