UPDATE `quest_template` SET `RequestItemsText` = 'Is everyone in order and ready to move?', `OfferRewardText` = 'Impressive work, $N. We should be ready to move out shortly. With our allies at our side, there is no way we can be defeated.' WHERE `Id` = 30568;
UPDATE `quest_template` SET `OfferRewardText` = 'You''re a sight for sore eyes, $C.$B$BI''ll be glad to help you Alliance fellas out. First though, you need to help me get my farm back.' WHERE `Id` = 30569;
UPDATE `quest_template` SET `OfferRewardText` = 'You''re a sight for sore eyes, $C.$B$BI''ll be glad to help you Horde fellas out. First though, you need to help me get my farm back.' WHERE `Id` = 30570;
UPDATE `quest_template` SET `RequestItemsText` = 'Look, $g mister : lady;, I don''t mean to be telling you your business, but I can still see a lot of my farmhands still out there.', `OfferRewardText` = 'Now ain''t you just the thing?$B$BThough, I guess it''s not fair to force these here workers to stay with us, now that we don''t have much work for ''em...' WHERE `Id` = 30571;
UPDATE `quest_template` SET `RequestItemsText` = 'It''s going to take more yaks than that to get this place back into fightin'' condition, $N, yes it is.', `OfferRewardText` = 'These yaks will do the trick nicely. Good work, $p. I''m feeling better about this whole situation already.' WHERE `Id` = 30575;
