UPDATE `quest_template` SET `RequestItemsText` = 'Well... ya'' got my meat?', `OfferRewardText` = 'Good work! I''m telliin'' ye, these Kun-Lai meaty bits are grade A goodness!' WHERE `Id` = 30583;
UPDATE `quest_template` SET `RequestItemsText` = 'Were you able to catch the eels?', `OfferRewardText` = 'These look like some tasty eels $N!  I''m sure you will love them!' WHERE `Id` = 30584;
