UPDATE `quest_template` SET `RequestItemsText` = 'What have you brought for Kovok?', `OfferRewardText` = 'Yes, a worthy feast.$B$BWell done.' WHERE `Id` = 31024;
UPDATE `quest_template` SET `RequestItemsText` = 'The swarm knows not of their terrible folly! These precious trees must be protected at all costs!', `OfferRewardText` = 'Thank you, Wakener. Kypari Zar can now dream in peace.$B$BHowever, the beast was merely a vessel for the corruption.$B$BNo... the true corruption lies much deeper.' WHERE `Id` = 31026;
