UPDATE `quest_template` SET `OfferRewardText` = 'You have come. Good. This is a calamitous situation.' WHERE `Id` = 31031;
UPDATE `quest_template` SET `RequestItemsText` = 'Some of them can make it through the smoke, but in small enough numbers that we can easily pick them off.', `OfferRewardText` = 'Your help is appreciated, stranger.' WHERE `Id` = 31032;
UPDATE `quest_template` SET `OfferRewardText` = 'I''ve been expecting your arrival, $N.' WHERE `Id` = 31034;
UPDATE `quest_template` SET `OfferRewardText` = 'I''ve been expecting your arrival, $N.' WHERE `Id` = 31036;
UPDATE `quest_template` SET `OfferRewardText` = 'I''ve been expecting your arrival, $N.' WHERE `Id` = 31037;
UPDATE `quest_template` SET `OfferRewardText` = 'Ahhhh, so you bested Snow Blossom in battle, did you?$B$BShe will be stinging from that loss for a while, I''d wager.$B$BHowever, you have done well to win her to your side.$B$BShe does not warm to strangers quickly, but through time, she will prove to be a loyal and dependable companion.' WHERE `Id` = 31038;
UPDATE `quest_template` SET `OfferRewardText` = 'The Shan''ze are up to something. Well done, $N, but we must continue to monitor their actions.' WHERE `Id` = 31039;
UPDATE `quest_template` SET `OfferRewardText` = 'Good work, $C. Left unchecked, the sprites would soon outnumber our entire army.' WHERE `Id` = 31040;
