UPDATE `quest_template` SET `RequestItemsText` = 'Knowledge is powerful. That is why the mogu are so dangerous.', `OfferRewardText` = 'Well done, $N.$B$BWe''ll begin deciphering the writing on these tablets at once.' WHERE `Id` = 31043;
UPDATE `quest_template` SET `RequestItemsText` = 'The quilen are fierce, but I see fierceness in your eyes as well.', `OfferRewardText` = 'These claws will come in handy.$B$BGood work, $C.' WHERE `Id` = 31044;
UPDATE `quest_template` SET `OfferRewardText` = 'I knew you could do this, $N!$B$BWith fewer Shan''ze Illusionists to stand against us, our task here will be much easier.' WHERE `Id` = 31045;
