UPDATE `quest_template` SET `RequestItemsText` = 'Azzix, his name was. I think. Azzix K''tai.', `OfferRewardText` = 'We''re not here to hurt anybody. We just want to make a little bit of brew out of this tree sap. Is that too much to ask?' WHERE `Id` = 31067;
UPDATE `quest_template` SET `RequestItemsText` = 'Is that some sort of scroll?$B$bWould you mind if I took a look?', `OfferRewardText` = '<Lya reads the entirety of the message.>$B$bThis scroll, this... this prophecy...$B$bIt''s terrifying!' WHERE `Id` = 31068;
UPDATE `quest_template` SET `RequestItemsText` = 'You needn''t look far to find shade around here, friend.', `OfferRewardText` = 'Beautiful. This will make a fine addition to our brew.$B$bThe most dangerous ingredients are quite often the most delicious.' WHERE `Id` = 31069;
UPDATE `quest_template` SET `RequestItemsText` = 'I wonder how we''ll mix those things into the brew? Can''t grind them up - that''d be too gritty.$B$bMaybe I''ll just soak ''em for a while.', `OfferRewardText` = 'I never thought of putting mushan teeth in a brew before.$B$bThat scroll''s got some wacky ideas.' WHERE `Id` = 31070;
UPDATE `quest_template` SET `RequestItemsText` = 'I think I''m starting to understand the next few lines of this prophecy, $N.$B$bDo you have the daggers yet?', `OfferRewardText` = 'These daggers, look!$B$B<Lya holds the blades hilt-to-hilt.>$B$bThey were built to fit together! But how to join them...?' WHERE `Id` = 31072;
UPDATE `quest_template` SET `RequestItemsText` = 'We don''t brew with wood here. It gives the brew a harsh, insipid flavor, not unlike that of wine.$B$B<Vu spits.>', `OfferRewardText` = 'I''ll get these pieces prepared.$B$bWe''ve already gathered quite a few of these ingredients! I''ll have to get a pot boiling soon.' WHERE `Id` = 31073;
UPDATE `quest_template` SET `RequestItemsText` = '<Lya looks concerned.>', `OfferRewardText` = '$N, look! The daggers - they''ve bound together, into a forked blade.$B$bWe are on the right track. I knew this wasn''t a beer recipe.' WHERE `Id` = 31074;
UPDATE `quest_template` SET `OfferRewardText` = 'It''s been a while since I brewed on the road.' WHERE `Id` = 31075;
UPDATE `quest_template` SET `OfferRewardText` = '<Chen listens intently.>$B$BBig Dan, Han, Evie, and Mama. I understand.$B$BIt seems like Dan will be safe here. I will go look for Evie, Han, and Mama Stormstout.$B$BTravel well, $N, and follow the Wanderer''s Way.' WHERE `Id` = 31076;
UPDATE `quest_template` SET `RequestItemsText` = '<Chen is in mourning.>', `OfferRewardText` = '<Chen is, for the moment, silent.>' WHERE `Id` = 31077;
