UPDATE `quest_template` SET `RequestItemsText` = 'We hate being eaten.', `OfferRewardText` = 'It is good to have someone of your colossal size in our village.$B$bYou have many uses.' WHERE `Id` = 31079;
UPDATE `quest_template` SET `RequestItemsText` = 'I haven''t been able to catch any of those things!', `OfferRewardText` = 'YEAH!!! FLITTERLING DUST!!!$B$B<Olon throws the powder into the pot.>$B$bThis brew is turning out... strange, and pretty smelly. I''m starting to think maybe Lya was right.' WHERE `Id` = 31080;
