UPDATE `quest_template` SET `OfferRewardText` = 'It is good you showed up when you did.$B$bPerhaps you are not as useless as I thought...$B$bThe Klaxxi''va sing to the paragon now. Soon they will know where to send you. For now there are other tasks.' WHERE `Id` = 31087;
UPDATE `quest_template` SET `RequestItemsText` = 'Have the harvesters been punished?', `OfferRewardText` = 'The Klaxxi are pleased with our work, outsider. You have proven to be more resourceful than we thought.' WHERE `Id` = 31088;
