UPDATE `quest_template` SET `OfferRewardText` = 'You''re a quick learner, $N.' WHERE `Id` = 31142;
UPDATE `quest_template` SET `RequestItemsText` = 'Kill the goblin assassins!', `OfferRewardText` = 'That will teach those monsters! They''ll think twice before taking another mercenary job for orcs.' WHERE `Id` = 31144;
