UPDATE `quest_template` SET `RequestItemsText` = 'Ahh, you have come.', `OfferRewardText` = 'We will honor our respective peoples by learning from each other. You will become a great $C, if I have anything to say about it. And I will learn the ways of your people.' WHERE `Id` = 31156;
UPDATE `quest_template` SET `OfferRewardText` = 'Good, good. Your first challenge surpassed. We will learn much from each other, I can see.' WHERE `Id` = 31157;
