UPDATE `quest_template` SET `RequestItemsText` = 'Ah, I am pleased to meet you.', `OfferRewardText` = 'I am honored that Chief Hawkwind would allow me to train you and grant you your rite of passage. While I am a master in the ways of the $C, I am but a child in the ways of your people.' WHERE `Id` = 31165;
UPDATE `quest_template` SET `OfferRewardText` = 'You have done well, $N.' WHERE `Id` = 31166;
UPDATE `quest_template` SET `OfferRewardText` = 'Not so different, you and I.$B$bI believe we can become good friends.' WHERE `Id` = 31167;
