UPDATE `quest_template` SET `OfferRewardText` = 'I recognize those mandibles. Karanosh ate my brother, you know.$B$BOf course, I have millions of brothers.$B$B<Zikk cackles.>' WHERE `Id` = 31599;
UPDATE `quest_template` SET `RequestItemsText` = 'Some of the corrupted kypari were shattered during the swarm''s horrid march, casting slivers of sha-infested amber across the land.$B$BBring me any that you find in your travels, so that they may be disposed of properly.', `OfferRewardText` = 'As long as these shards blanket the land, our home will be a place of fear and death.' WHERE `Id` = 31603;
UPDATE `quest_template` SET `OfferRewardText` = '<From the looks of it, this mantid was just recently broken out of his chamber. He lets out a hacking cough.>$B$B...Diss-ec...tor... has... returned...' WHERE `Id` = 31605;
