UPDATE `quest_template` SET `OfferRewardText` = 'A good defense is just as effective as a strong offense. One less enemy to worry about.$B$BWell done.' WHERE `Id` = 32517;
UPDATE `quest_template` SET `OfferRewardText` = 'Your skills are impressive indeed. Thank you for doing this for me, $N.' WHERE `Id` = 32520;
UPDATE `quest_template` SET `OfferRewardText` = 'You have our gratitude, $N.' WHERE `Id` = 32521;
UPDATE `quest_template` SET `OfferRewardText` = 'One less threat at our doorstep. Thank you, $N.' WHERE `Id` = 32522;
